export const DISTRO_LABEL = {"ubuntu":"Ubuntu","debian":"Debian","fedora":"Fedora","arch":"Arch","alpine":"Alpine","kali":"Kali","parrot":"Parrot OS","almalinux":"AlmaLinux","rocky":"Rocky Linux","oracle":"Oracle Linux","centos":"CentOS","opensuse":"openSUSE","remnux":"REMnux","mint":"Mint-style","zorin":"Zorin-style","pop":"Pop-style","elementary":"elementary-style","garuda":"Garuda-style","generic-mac":"Mac-like","generic-win":"Windows-like"};
export const distroLogo = (family) => DISTRO[family] || DISTRO.generic;
export const distroLabel = (family) => DISTRO_LABEL[family] || (family ? family[0].toUpperCase() + family.slice(1) : "");
